package tz.go.bukobamc.meetings.api;

import org.apache.commons.csv.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import org.springframework.web.server.ResponseStatusException;
import tz.go.bukobamc.meetings.model.*; import tz.go.bukobamc.meetings.repo.*; import tz.go.bukobamc.meetings.security.SessionService;
import tz.go.bukobamc.meetings.service.NotificationService;
import java.io.*; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.time.format.DateTimeFormatter; import java.util.*;

@RestController @RequestMapping("/api")
public class MeetingController {
 private final UserRepository users; private final MeetingRepository meetings; private final GuestRepository guests; private final InvitationRepository invitations; private final OTPVerificationRepository otps; private final QRSessionRepository qrSessions; private final AttendanceRecordRepository attendance; private final SessionService sessions; private final NotificationService notifications; private final String baseUrl; private final String defaultWhatsappSender; private final String defaultEmailSender; private final boolean whatsappEnabled; private final String appEnv;
 public MeetingController(UserRepository u,MeetingRepository m,GuestRepository g,InvitationRepository i,OTPVerificationRepository o,QRSessionRepository q,AttendanceRecordRepository a,SessionService s,NotificationService n,@Value("${bmc.public-base-url}")String b,@Value("${bmc.default-whatsapp-sender}")String sender,@Value("${bmc.default-email-sender}")String email,@Value("${bmc.whatsapp-enabled:false}")boolean enabled,@Value("${APP_ENV:development}")String env){users=u;meetings=m;guests=g;invitations=i;otps=o;qrSessions=q;attendance=a;sessions=s;notifications=n;baseUrl=b;defaultWhatsappSender=sender;defaultEmailSender=email;whatsappEnabled=enabled;appEnv=env;}
 private User auth(String h){return sessions.require(h);}
 private static String hash(String x){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(x.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private static boolean past(Meeting m){return m.endAt!=null&&!m.endAt.isAfter(OffsetDateTime.now());}
 private static void ensureEditable(Meeting m){if(past(m))throw new ResponseStatusException(HttpStatus.CONFLICT,"Past meetings are read-only");}
 private void cleanupPending(){for(User u:users.findByStatusAndCreatedAtBefore("pending",OffsetDateTime.now().minusHours(24))){otps.deleteByUserId(u.id);users.delete(u);}}
 private String issueOtp(User u,String channel){if(!channel.equals("email")&&!channel.equals("phone"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Channel must be email or phone");String alphabet="ABCDEFGHJKLMNPQRSTUVWXYZ23456789";StringBuilder generated=new StringBuilder(6);SecureRandom random=new SecureRandom();for(int i=0;i<6;i++)generated.append(alphabet.charAt(random.nextInt(alphabet.length())));String code=generated.toString();OTPVerification v=otps.findTopByUserIdAndChannelAndUsedFalseOrderByIdDesc(u.id,channel).orElseGet(OTPVerification::new);v.user=u;v.channel=channel;v.codeHash=hash(code);v.expiresAt=OffsetDateTime.now().plusMinutes(10);v.attemptCount=0;v.used=false;v.resendCount++;v.lastSentAt=OffsetDateTime.now();otps.save(v);String message="Your BMC-MMS "+channel+" OTP is "+code+". It expires in 10 minutes and can be used once.";if(channel.equals("email")){if("development".equalsIgnoreCase(appEnv))System.out.println("[DEV OTP] email="+u.email+" code="+code);notifications.email(u.email,"BMC-MMS verification code",message);}else notifications.whatsapp(u.phone,message);return code;}
 private static String newToken(){return Base64.getUrlEncoder().withoutPadding().encodeToString(UUID.randomUUID().toString().getBytes(StandardCharsets.UTF_8));}
 @GetMapping("/health") public Map<String,String> health(){return Map.of("status","ok","service","bmc-meetings-springboot");}
 public record Login(String email,String password){} public record Register(String name,String email,String phone,String password){} public record Verify(String email,String channel,String code){} public record Resend(String email,String channel){} public record ProfileIn(String name,String phone){} public record MeetingIn(String title,String purpose,OffsetDateTime start_at,OffsetDateTime end_at,String location,String map_link,String virtual_link,String department,String meeting_type,String priority,String status){} public record GuestIn(String name,String phone,String email,String role_title,String organization){} public record RsvpIn(String status,String reason,String language){} public record AttendanceIn(String personal_token,String qr_payload){}
 @PostMapping("/auth/register") public Object register(@RequestBody Register x){cleanupPending();String email=x.email().trim().toLowerCase(),phone=x.phone().trim();if(users.findByEmail(email).filter(u->u.active||!"pending".equals(u.status)).isPresent()||users.findByPhone(phone).filter(u->u.active||!"pending".equals(u.status)).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Email or phone is already verified by another account");User u=users.findByEmail(email).orElseGet(User::new);u.name=x.name();u.email=email;u.phone=phone;u.passwordHash=hash(x.password());u.role="organizer";u.status="pending";u.active=false;u.emailVerified=false;u.phoneVerified=!whatsappEnabled;u=users.save(u);String emailCode=issueOtp(u,"email");if(whatsappEnabled)issueOtp(u,"phone");Map<String,Object> result=new LinkedHashMap<>();result.put("status","pending");result.put("message",whatsappEnabled?"Enter the Email OTP and WhatsApp OTP sent to your contacts":"Enter the Email OTP sent to your email address");if("development".equalsIgnoreCase(appEnv))result.put("development_email_otp",emailCode);return result;}
 @PostMapping("/auth/verify") public Object verify(@RequestBody Verify x){User u=users.findByEmail(x.email().trim().toLowerCase()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Registration not found"));if(!"pending".equals(u.status))return Map.of("status","active");if("phone".equals(x.channel())&&!whatsappEnabled)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"WhatsApp verification is disabled for now; verify email only");OTPVerification v=otps.findTopByUserIdAndChannelAndUsedFalseOrderByIdDesc(u.id,x.channel()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"No active OTP for this channel"));if(v.expiresAt.isBefore(OffsetDateTime.now()))throw new ResponseStatusException(HttpStatus.GONE,"OTP expired; request a new code");if(++v.attemptCount>5||!hash(x.code()).equals(v.codeHash)){otps.save(v);throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid OTP");}v.used=true;otps.save(v);if("email".equals(x.channel()))u.emailVerified=true;else if("phone".equals(x.channel()))u.phoneVerified=true;else throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Channel must be email or phone");if(u.emailVerified&&(u.phoneVerified||!whatsappEnabled)){u.status="active";u.active=true;}users.save(u);return Map.of("status",u.status,"verified",x.channel());}
 @PostMapping("/auth/resend") public Object resend(@RequestBody Resend x){User u=users.findByEmail(x.email().trim().toLowerCase()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Registration not found"));if(!"email".equals(x.channel())&&!"phone".equals(x.channel()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Channel must be email or phone");if("phone".equals(x.channel())&&!whatsappEnabled)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"WhatsApp verification is disabled for now; verify email only");OTPVerification old=otps.findTopByUserIdAndChannelAndUsedFalseOrderByIdDesc(u.id,x.channel()).orElse(null);if(old!=null&&old.lastSentAt!=null&&old.lastSentAt.plusSeconds(60).isAfter(OffsetDateTime.now()))throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Wait 60 seconds before resending");if(old!=null&&old.resendCount>=5&&old.lastSentAt.plusMinutes(30).isAfter(OffsetDateTime.now()))throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Resend limit reached; try again later");String code=issueOtp(u,x.channel());Map<String,Object> result=new LinkedHashMap<>();result.put("status","sent");result.put("channel",x.channel());if("development".equalsIgnoreCase(appEnv)&&"email".equals(x.channel()))result.put("development_email_otp",code);return result;}
 @PostMapping("/auth/login") public Object login(@RequestBody Login x){return users.findByEmail(x.email().trim().toLowerCase()).filter(u->hash(x.password()).equals(u.passwordHash)&&u.active&&"active".equals(u.status)).map(u->Map.of("access_token",sessions.create(u),"user",Map.of("name",u.name,"role",u.role,"email",u.email))).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email, password, or unverified account"));}
 @GetMapping("/me") public Object me(@RequestHeader("Authorization")String h){User u=auth(h);return Map.of("name",u.name,"role",u.role,"email",u.email,"phone",Objects.toString(u.phone,""));}
 @PutMapping("/me") public Object updateProfile(@RequestHeader("Authorization")String h,@RequestBody ProfileIn x){User u=auth(h);if(x.name()!=null&&!x.name().isBlank())u.name=x.name();if(x.phone()!=null&&!x.phone().isBlank())u.phone=x.phone();users.save(u);return Map.of("name",u.name,"phone",Objects.toString(u.phone,""));}
 @GetMapping("/meetings") public Object list(@RequestHeader("Authorization")String h){User u=auth(h);return meetings.findAll().stream().filter(m->"admin".equals(u.role)||Objects.equals(m.createdBy,u.id)).map(m->{Map<String,Object> x=new LinkedHashMap<>();x.put("id",m.id);x.put("reference",m.reference);x.put("title",m.title);x.put("start_at",m.startAt);x.put("end_at",m.endAt);x.put("location",Objects.toString(m.location,""));x.put("status",m.status);x.put("past",past(m));x.put("guest_count",guests.countByMeetingId(m.id));return x;}).toList();}
 @PostMapping("/meetings") public Object create(@RequestHeader("Authorization")String h,@RequestBody MeetingIn x){User u=auth(h);if(x.start_at()==null||x.end_at()==null)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Meeting start and end date are required");if(x.start_at().isBefore(OffsetDateTime.now()))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Meeting start must be in the future");if(!x.end_at().isAfter(x.start_at()))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Meeting end must be later than the start time");Meeting m=new Meeting();m.reference="BMC-"+LocalDate.now()+"-"+UUID.randomUUID().toString().substring(0,4).toUpperCase();m.createdBy=u.id;m.title=x.title();m.purpose=x.purpose();m.startAt=x.start_at();m.endAt=x.end_at();m.location=x.location();m.mapLink=x.map_link();m.virtualLink=x.virtual_link();m.department=x.department();m.meetingType=x.meeting_type()==null?"internal":x.meeting_type();m.priority=x.priority()==null?"normal":x.priority();m.status=x.status()==null?"draft":x.status();m=meetings.save(m);return Map.of("id",m.id,"reference",m.reference);}
 @PutMapping("/meetings/{id}") public Object update(@RequestHeader("Authorization")String h,@PathVariable Long id,@RequestBody MeetingIn x){User u=auth(h);Meeting m=meetings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Meeting not found"));if(!"admin".equals(u.role)&&!Objects.equals(m.createdBy,u.id))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the organiser or admin may edit this meeting");ensureEditable(m);if(x.start_at()==null||x.end_at()==null||!x.end_at().isAfter(x.start_at()))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"End time must be after start time");m.title=x.title();m.purpose=x.purpose();m.startAt=x.start_at();m.endAt=x.end_at();m.location=x.location();m.mapLink=x.map_link();m.virtualLink=x.virtual_link();m.department=x.department();return meetings.save(m);}
 @GetMapping("/meetings/{id}") public Object detail(@RequestHeader("Authorization")String h,@PathVariable Long id){User u=auth(h);Meeting m=meetings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Meeting not found"));if(!"admin".equals(u.role)&&!Objects.equals(m.createdBy,u.id))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Meeting not found");List<Map<String,Object>> gs=new ArrayList<>();Map<String,Integer> counts=new HashMap<>(Map.of("confirmed",0,"declined",0,"tentative",0,"no_response",0));for(Guest g:guests.findByMeetingId(id)){Invitation in=invitations.findByMeetingId(id).stream().filter(i->Objects.equals(i.guest.id,g.id)).findFirst().orElse(null);String st=in!=null&&in.response!=null?in.response.status:"no_response";counts.put(st,counts.getOrDefault(st,0)+1);gs.add(Map.of("id",g.id,"name",g.name,"phone",Objects.toString(g.phone,""),"email",Objects.toString(g.email,""),"organization",Objects.toString(g.organization,""),"status",st,"reason",in!=null&&in.response!=null?Objects.toString(in.response.reason,""):""));}Map<String,Object> result=new LinkedHashMap<>();result.put("id",m.id);result.put("reference",m.reference);result.put("title",m.title);result.put("purpose",Objects.toString(m.purpose,""));result.put("start_at",m.startAt);result.put("end_at",m.endAt);result.put("location",Objects.toString(m.location,""));result.put("map_link",Objects.toString(m.mapLink,""));result.put("virtual_link",Objects.toString(m.virtualLink,""));result.put("department",Objects.toString(m.department,""));result.put("meeting_type",m.meetingType);result.put("priority",m.priority);result.put("status",m.status);result.put("counts",counts);result.put("guests",gs);return result;}
 @PostMapping("/meetings/{id}/guests") public Object addGuest(@RequestHeader("Authorization")String h,@PathVariable Long id,@RequestBody GuestIn x){auth(h);Meeting m=meetings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Meeting not found"));ensureEditable(m);if((x.phone()==null||x.phone().isBlank())&&(x.email()==null||x.email().isBlank()))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Phone or email is required");Guest g=new Guest();g.meeting=m;g.name=x.name();g.phone=x.phone();g.email=x.email();g.roleTitle=x.role_title();g.organization=x.organization();return Map.of("id",guests.save(g).id);}
 @PostMapping("/meetings/{id}/guests/import") public Object importCsv(@RequestHeader("Authorization")String h,@PathVariable Long id,@RequestParam MultipartFile file)throws IOException{auth(h);Meeting m=meetings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Meeting not found"));ensureEditable(m);int added=0,row=1;List<Map<String,Object>> skipped=new ArrayList<>();try(CSVParser p=CSVParser.parse(new InputStreamReader(file.getInputStream(),StandardCharsets.UTF_8),CSVFormat.DEFAULT.builder().setHeader().setSkipHeaderRecord(true).build())){for(CSVRecord r:p){row++;String name=r.get("name"),phone=r.get("phone"),email=r.get("email");if(name==null||name.isBlank()||((phone==null||phone.isBlank())&&(email==null||email.isBlank()))){skipped.add(Map.of("row",row,"reason","name and phone or email required"));continue;}Guest g=new Guest();g.meeting=m;g.name=name;g.phone=phone;g.email=email;g.roleTitle=r.get("role_title");g.organization=r.get("organization");guests.save(g);added++;}}return Map.of("added",added,"skipped",skipped);}
 @PostMapping("/meetings/{id}/send-invites") public Object invite(@RequestHeader("Authorization")String h,@PathVariable Long id){User creator=auth(h);Meeting m=meetings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Meeting not found"));ensureEditable(m);String sender=creator.phone!=null&&!creator.phone.isBlank()?creator.phone:defaultWhatsappSender;List<Map<String,Object>> out=new ArrayList<>();for(Guest g:guests.findByMeetingId(id)){String raw=newToken();Invitation i=new Invitation();i.meeting=m;i.guest=g;i.tokenHash=hash(raw);i.deliveryStatus="sent";i.sentAt=OffsetDateTime.now();invitations.save(i);String rsvp=baseUrl+"/rsvp.html?token="+raw,signIn=baseUrl+"/attendance.html?token="+raw,calendar=baseUrl+"/api/rsvp/"+raw+"/calendar.ics";String body="BMC-MMS meeting: "+m.title+"\nDate: "+m.startAt+"\nLocation: "+Objects.toString(m.location,"")+"\nRSVP: "+rsvp+"\nPersonal Sign-In Link: "+signIn+"\nCalendar: "+calendar; if(g.phone!=null&&!g.phone.isBlank())notifications.whatsapp(g.phone,body);else notifications.email(g.email,"BMC-MMS meeting invitation: "+m.title,body);out.add(Map.of("guest",g.name,"rsvp_link",rsvp,"personal_sign_in_link",signIn,"calendar_link",calendar,"channel",g.phone!=null&&!g.phone.isBlank()?"whatsapp":"email","status","sent"));}m.status="published";meetings.save(m);return Map.of("sent",out.size(),"results",out,"whatsapp_sender",sender,"email_sender",defaultEmailSender,"qr_not_included",true);}
 @GetMapping("/rsvp/{token}") public Object rsvpInfo(@PathVariable String token){Invitation i=invitations.findByTokenHash(hash(token)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Invalid RSVP link"));Meeting m=i.meeting;return Map.of("meeting",Map.of("reference",m.reference,"title",m.title,"purpose",Objects.toString(m.purpose,""),"start_at",m.startAt,"end_at",m.endAt,"location",Objects.toString(m.location,""),"map_link",Objects.toString(m.mapLink,""),"virtual_link",Objects.toString(m.virtualLink,"")),"guest",Map.of("name",i.guest.name),"token",token);}
 @PostMapping("/rsvp/{token}") public Object rsvp(@PathVariable String token,@RequestBody RsvpIn x){if(!Set.of("confirmed","declined","tentative").contains(x.status()))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Invalid RSVP status");if("declined".equals(x.status())&&(x.reason()==null||x.reason().isBlank()))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"A decline reason is required");Invitation i=invitations.findByTokenHash(hash(token)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Invalid RSVP link"));RsvpResponse r=i.response==null?new RsvpResponse():i.response;r.invitation=i;r.status=x.status();r.reason=x.reason();r.language=x.language()==null?"en":x.language();r.respondedAt=OffsetDateTime.now();i.response=r;invitations.save(i);return Map.of("status","saved","message","RSVP recorded");}
 @GetMapping("/meetings/{id}/attendance/qr") public Object attendanceQr(@RequestHeader("Authorization")String h,@PathVariable Long id){User u=auth(h);Meeting m=meetings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Meeting not found"));if(!"admin".equals(u.role)&&!Objects.equals(m.createdBy,u.id))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the Organizer may display the Session QR Code");OffsetDateTime now=OffsetDateTime.now(),from=m.startAt.minusMinutes(15),to=m.endAt.plusMinutes(15);if(now.isBefore(from)||now.isAfter(to))throw new ResponseStatusException(HttpStatus.CONFLICT,"Attendance QR is available only during the meeting window");String raw=newToken();QRSession q=new QRSession();q.meeting=m;q.sessionTokenHash=hash(raw);q.issuedAt=now;q.expiresAt=now.plusSeconds(45);qrSessions.save(q);String payload="{\"meetingId\":"+m.id+",\"sessionToken\":\""+raw+"\",\"expiresAt\":\""+q.expiresAt+"\"}";return Map.of("meeting_id",m.id,"payload",payload,"issued_at",q.issuedAt,"expires_at",q.expiresAt);}
 @GetMapping("/attendance/{token}") public Object attendanceInfo(@PathVariable String token){Invitation i=invitations.findByTokenHash(hash(token)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Personal Sign-In Link expired"));AttendanceRecord a=attendance.findByMeetingIdAndParticipantId(i.meeting.id,i.guest.id).orElse(null);return Map.of("meeting",Map.of("title",i.meeting.title,"start_at",i.meeting.startAt,"end_at",i.meeting.endAt,"location",Objects.toString(i.meeting.location,"")),"participant",i.guest.name,"attended",a!=null&&a.used);}
 @PostMapping("/attendance/sign-in") public Object attendanceSignIn(@RequestBody AttendanceIn x){Invitation i=invitations.findByTokenHash(hash(x.personal_token())).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Personal Sign-In Link expired"));AttendanceRecord existing=attendance.findByMeetingIdAndParticipantId(i.meeting.id,i.guest.id).orElse(null);if(existing!=null&&existing.used)throw new ResponseStatusException(HttpStatus.CONFLICT,"You are already marked as attended");Map<?,?> payload;try{payload=new com.fasterxml.jackson.databind.ObjectMapper().readValue(x.qr_payload(),Map.class);}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid Session QR Code");}if(!Objects.equals(String.valueOf(payload.get("meetingId")),String.valueOf(i.meeting.id)))throw new ResponseStatusException(HttpStatus.CONFLICT,"Wrong meeting QR Code");String qr=String.valueOf(payload.get("sessionToken"));QRSession session=qrSessions.findBySessionTokenHash(hash(qr)).orElseThrow(()->new ResponseStatusException(HttpStatus.GONE,"QR expired — rescan the live Session QR Code"));if(!session.meeting.id.equals(i.meeting.id))throw new ResponseStatusException(HttpStatus.CONFLICT,"Wrong meeting QR Code");if(session.expiresAt.isBefore(OffsetDateTime.now()))throw new ResponseStatusException(HttpStatus.GONE,"QR expired — rescan the live Session QR Code");AttendanceRecord a=existing==null?new AttendanceRecord():existing;a.meeting=i.meeting;a.participantId=i.guest.id;a.personalTokenHash=hash(x.personal_token());a.signedInAt=OffsetDateTime.now();a.used=true;attendance.save(a);return Map.of("status","attended","signed_in_at",a.signedInAt,"message","Attendance recorded successfully");}
 @GetMapping(value="/rsvp/{token}/calendar.ics",produces="text/calendar") public ResponseEntity<String> calendar(@PathVariable String token){Invitation i=invitations.findByTokenHash(hash(token)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Invalid RSVP link"));Meeting m=i.meeting;DateTimeFormatter f=DateTimeFormatter.ofPattern("yyyyMMdd'T'HHmmss'Z'");String body="BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Bukoba Municipal Council//Meetings//EN\r\nBEGIN:VEVENT\r\nUID:"+m.reference+"@bukobamc.go.tz\r\nDTSTAMP:"+OffsetDateTime.now(ZoneOffset.UTC).format(f)+"\r\nDTSTART:"+m.startAt.withOffsetSameInstant(ZoneOffset.UTC).format(f)+"\r\nDTEND:"+m.endAt.withOffsetSameInstant(ZoneOffset.UTC).format(f)+"\r\nSUMMARY:"+ics(m.title)+"\r\nDESCRIPTION:"+ics(Objects.toString(m.purpose,""))+"\r\nLOCATION:"+ics(Objects.toString(m.location,""))+"\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n";return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename="+m.reference+".ics").body(body);}
 private static String ics(String x){return Objects.toString(x,"").replace("\\","\\\\").replace(";","\\;").replace(",","\\,").replace("\n","\\n");}
 @GetMapping(value="/meetings/{id}/report.csv",produces="text/csv") public ResponseEntity<String> report(@RequestHeader("Authorization")String h,@PathVariable Long id){auth(h);Meeting m=meetings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Meeting not found"));List<Invitation> meetingInvitations=invitations.findByMeetingId(id);StringBuilder csv=new StringBuilder("Meeting reference,"+m.reference+"\nName,Phone,Email,Organization,RSVP status,Reason\n");for(Guest g:guests.findByMeetingId(id)){Invitation i=meetingInvitations.stream().filter(x->Objects.equals(x.guest.id,g.id)).findFirst().orElse(null);String status=i!=null&&i.response!=null?i.response.status:"no_response";String reason=i!=null&&i.response!=null?Objects.toString(i.response.reason,""):"";csv.append(String.join(",",csv(g.name),csv(g.phone),csv(g.email),csv(g.organization),status,csv(reason))).append("\n");}return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename="+m.reference+"-attendance.csv").body(csv.toString());}
 private static String csv(String value){String x=Objects.toString(value,"").replace("\"","\"\"");return "\""+x+"\"";}
}
